import{_ as a,C as o,o as n,c as i,ai as t,E as s}from"./chunks/framework.DRi5ScqO.js";const m=JSON.parse(`{"title":"Features","description":"Every VERA feature, included for everyone at one price set by your agency's revenue, with a side-by-side comparison against Harvest.","frontmatter":{"description":"Every VERA feature, included for everyone at one price set by your agency's revenue, with a side-by-side comparison against Harvest."},"headers":[],"relativePath":"features.md","filePath":"features.md"}`),d={name:"features.md"};function l(h,e,c,g,u,p){const r=o("CostCompare");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>Everything on this page is included for every agency on VERA. There are no feature tiers, no seat counts, and no usage charges for adding another project, client or invoice. You pay one monthly price set by your agency&#39;s annual revenue (<a href="/pricing.html">see Pricing</a>), and everyone on your team gets all of it.</p><h2 id="coming-from-harvest" tabindex="-1">Coming from Harvest? <a class="header-anchor" href="#coming-from-harvest" aria-label="Permalink to &quot;Coming from Harvest?&quot;">​</a></h2><p>Harvest is a good time tracker. If you&#39;re shopping around, it is usually for one of three reasons: the per-seat bill grows every time you hire, the reports you need are on a higher plan, or you need to know whether a project is making money while there&#39;s still time to act.</p><h3 id="what-a-small-agency-pays" tabindex="-1">What a small agency pays <a class="header-anchor" href="#what-a-small-agency-pays" aria-label="Permalink to &quot;What a small agency pays&quot;">​</a></h3><p>In 2026 Harvest moved paid accounts to per-seat pricing plus a usage fee, and renewals arrived at about ten times the old bill. One seven-person business went from $69 to <a href="https://www.subscriptioninsider.com/blog/harvest-pricing-change-sends-some-renewals-up-1-500" target="_blank" rel="noreferrer">$821.50 a month</a>.<sup><a href="#notes">*</a></sup> VERA charges one monthly price set by your revenue, so a small agency pays less for VERA than for Harvest.</p>',6)),s(r),e[1]||(e[1]=t('<p>The table below compares the two products feature by feature. Harvest&#39;s column is taken from the comparison table on <a href="https://www.getharvest.com/pricing" target="_blank" rel="noreferrer">Harvest&#39;s pricing page</a>, read on October 4, 2026; check there for their current terms. A dash means the feature isn&#39;t listed on that page.</p><h3 id="how-you-pay" tabindex="-1">How you pay <a class="header-anchor" href="#how-you-pay" aria-label="Permalink to &quot;How you pay&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Harvest</th><th>VERA</th></tr></thead><tbody><tr><td>Pricing model</td><td>Per seat, per month</td><td>One price per month, set by annual revenue</td></tr><tr><td>Plans</td><td>Free (1 seat, 2 projects), Teams, Enterprise, Enterprise Plus</td><td>One plan with everything</td></tr><tr><td>Price</td><td>Teams $9–$11 per seat per month; Enterprise $14–$17.50 per seat per month (the lower figure billed annually)</td><td>$199–$1,999 per month by revenue band</td></tr><tr><td>Hiring someone</td><td>Adds a seat</td><td>Changes nothing</td></tr><tr><td>More projects, clients, invoices</td><td>Billed on usage as your team grows</td><td>Unlimited, included</td></tr><tr><td>Resource planning</td><td>Harvest Forecast, $5–$6.25 per person per month extra</td><td>Included</td></tr></tbody></table><h3 id="where-vera-goes-further" tabindex="-1">Where VERA goes further <a class="header-anchor" href="#where-vera-goes-further" aria-label="Permalink to &quot;Where VERA goes further&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Harvest</th><th>VERA</th></tr></thead><tbody><tr><td>Profitability by client, project and team</td><td>Enterprise only</td><td>Included</td></tr><tr><td>Timesheet approval before billing</td><td>Enterprise only</td><td>Included, for time-and-materials work</td></tr><tr><td>Audit trail of every entry and edit</td><td>Enterprise only</td><td>Included</td></tr><tr><td>Billable and cost rates per person</td><td>Teams and up</td><td>Included, with the full rate history</td></tr><tr><td>Team capacity and utilization</td><td>Teams and up</td><td>Included, week by week, with a capacity heatmap</td></tr><tr><td>Revenue recognized as work happens</td><td>—</td><td>Every entry updates revenue, cost and margin</td></tr><tr><td>Retainers run as periods, each with its own budget</td><td>—</td><td>Included, with renewal reminders</td></tr><tr><td>Labor efficiency ratio against your own target</td><td>—</td><td>Included, by project, client, discipline and PM</td></tr><tr><td>Monthly P&amp;L with contribution margin</td><td>—</td><td>Included</td></tr><tr><td>Revenue and cost forecast</td><td>—</td><td>Included, with what-if scenarios for open proposals</td></tr><tr><td>A morning briefing for every person</td><td>—</td><td>Included, by Slack or email</td></tr><tr><td>Advice on what each project needs next</td><td>—</td><td>Included</td></tr><tr><td>Fixed-fee vendor costs counted correctly</td><td>—</td><td>Included</td></tr><tr><td>Managers see project health, never anyone&#39;s pay</td><td>—</td><td>Enforced by role</td></tr><tr><td>Proposals costed and checked against capacity before you sign</td><td>Project estimates on every plan</td><td>Included, and a won proposal becomes the project</td></tr></tbody></table><h3 id="where-harvest-goes-further" tabindex="-1">Where Harvest goes further <a class="header-anchor" href="#where-harvest-goes-further" aria-label="Permalink to &quot;Where Harvest goes further&quot;">​</a></h3><p>VERA doesn&#39;t try to do everything Harvest does. If you rely on any of these, keep the tool you use for it today.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Harvest</th><th>VERA</th></tr></thead><tbody><tr><td>Invoicing</td><td>Every plan</td><td>No. VERA shows what each project earned and was scheduled to bill; your accounting tool sends the invoice.</td></tr><tr><td>Expense tracking</td><td>Every plan</td><td>No</td></tr><tr><td>One-click timers, desktop and mobile apps</td><td>Every plan</td><td>No timer. Time is entered in seconds in the web console, which works on a phone, or by Slack message.</td></tr><tr><td>QuickBooks, Xero and Stripe integrations</td><td>Teams and up</td><td>No</td></tr><tr><td>Custom report builder</td><td>Up to 4 reports, unlimited on Enterprise</td><td>No builder. A fixed set of reports, plus CSV export of every entry.</td></tr><tr><td>SAML single sign-on</td><td>Enterprise only</td><td>No. Sign in with Google.</td></tr><tr><td>Require a note on every entry</td><td>Enterprise only</td><td>No</td></tr><tr><td>50+ integrations</td><td>Every plan</td><td>Slack only</td></tr></tbody></table><h2 id="everything-vera-does" tabindex="-1">Everything VERA does <a class="header-anchor" href="#everything-vera-does" aria-label="Permalink to &quot;Everything VERA does&quot;">​</a></h2><h3 id="time" tabindex="-1">Time <a class="header-anchor" href="#time" aria-label="Permalink to &quot;Time&quot;">​</a></h3><ul><li><strong>Log time in seconds.</strong> Pick the project and task, type the hours. No weekly grid to reconstruct on Friday afternoon.</li><li><strong>Quick-log from an allocation.</strong> One click logs against the work you were allocated.</li><li><strong>Log by Slack message</strong> for teams that live in Slack: &quot;4h on the Acme rebrand, design.&quot;</li><li><strong>Your week at a glance</strong>, with each day marked as worked, a holiday, a weekend or time off, and your total against what a normal week expects.</li><li><strong>Edit and delete your own entries</strong>, with every retroactive change recorded.</li><li><strong>A gentle evening reminder</strong> when you&#39;ve logged less than your normal day. Part-time schedules get their own target.</li><li><strong>Company holidays recorded automatically</strong> as paid time off for full-time staff once the day has passed.</li><li><strong>Time off</strong>: request PTO, see your history, withdraw a pending request.</li></ul><h3 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h3><ul><li><strong>Every way agencies sell work</strong>: time and materials, fixed price, retainer, pro bono and internal.</li><li><strong>Revenue recognized the right way for each type</strong>: hours × rate, percentage of completion, or per retainer period.</li><li><strong>A burn-up chart</strong> of hours against budget, with the planned pace and the hours allocated.</li><li><strong>Schedule and budget health</strong> with the working shown: how many hours are recorded, what the plan expects by today, and how far off it is.</li><li><strong>Delivery view</strong>: planned against recorded hours for each person, week by week.</li><li><strong>Projected exhaustion</strong>: when the budget runs out at the current or planned pace.</li><li><strong>What this project needs</strong>: plain advice on the next thing to set up or fix, with a link to it.</li><li><strong>Change a project&#39;s type</strong> later, with its history recalculated.</li><li><strong>A billing schedule</strong> for fixed-price work, and a month-end view of scheduled against earned.</li></ul><h3 id="retainers" tabindex="-1">Retainers <a class="header-anchor" href="#retainers" aria-label="Permalink to &quot;Retainers&quot;">​</a></h3><ul><li><strong>Each period is its own window</strong>, with its own hours and contract value.</li><li><strong>Re-up in one click</strong> from the last period&#39;s terms.</li><li><strong>Judged on the period you&#39;re in</strong>, so last month&#39;s overrun can&#39;t hide this month&#39;s.</li><li><strong>Renewal reminders</strong> before a period ends with nothing lined up behind it.</li><li><strong>A different PM per period</strong> when the account changes hands.</li></ul><h3 id="allocations-and-capacity" tabindex="-1">Allocations and capacity <a class="header-anchor" href="#allocations-and-capacity" aria-label="Permalink to &quot;Allocations and capacity&quot;">​</a></h3><ul><li><strong>Allocate hours to a person, a project and a task</strong>, with as many allocations per person as the work needs.</li><li><strong>A window and a week-by-week shape</strong> for when the hours are expected to land.</li><li><strong>A capacity heatmap</strong>: everyone&#39;s committed hours against their availability, week by week, past weeks showing what was recorded.</li><li><strong>Time off and holidays counted</strong> in everyone&#39;s capacity.</li><li><strong>Overruns and unplanned time flagged</strong> for the PM, never blocked.</li></ul><h3 id="money" tabindex="-1">Money <a class="header-anchor" href="#money" aria-label="Permalink to &quot;Money&quot;">​</a></h3><ul><li><strong>A monthly P&amp;L</strong> with revenue, cost, profit, contribution margin and labor efficiency ratio.</li><li><strong>Cut by client, by discipline and by PM.</strong></li><li><strong>Estimates against actuals</strong> by project, client and discipline.</li><li><strong>Your own target labor efficiency ratio</strong>, company-wide or per project, with every figure colored against it.</li><li><strong>Cost from each person&#39;s rate on the date of the entry</strong>, with the full rate history kept.</li><li><strong>Fixed-fee vendors</strong> costed at their agreed fee, accrued over the project, not at an hourly rate.</li><li><strong>A forward forecast</strong> of revenue and cost, with what-if scenarios for proposals you might win.</li><li><strong>Time approval for time-and-materials projects</strong>: write hours down before they&#39;re billed, without changing what was recorded.</li><li><strong>CSV export</strong> of every time entry.</li></ul><h3 id="proposals" tabindex="-1">Proposals <a class="header-anchor" href="#proposals" aria-label="Permalink to &quot;Proposals&quot;">​</a></h3><ul><li><strong>Cost a proposal before you send it</strong>: staffing by person or discipline, vendor fees, and the margin it will earn.</li><li><strong>Check it against capacity</strong>: can the team actually take this on, week by week?</li><li><strong>Convert a won proposal</strong> into a real project, with its tasks and client in place.</li></ul><h3 id="people" tabindex="-1">People <a class="header-anchor" href="#people" aria-label="Permalink to &quot;People&quot;">​</a></h3><ul><li><strong>Roles</strong>: owner, admin, manager and team member, each seeing exactly what they should.</li><li><strong>Managers see percentages and their own projects</strong>, never pay rates or what anyone costs.</li><li><strong>Team members see their own time</strong> and nothing else.</li><li><strong>Salary bands by discipline and level</strong>, compared against each person&#39;s pay, owners only.</li><li><strong>Contributions over time</strong> for each person, against their own capacity.</li></ul><h3 id="the-daily-rhythm" tabindex="-1">The daily rhythm <a class="header-anchor" href="#the-daily-rhythm" aria-label="Permalink to &quot;The daily rhythm&quot;">​</a></h3><ul><li><strong>A morning briefing for everyone</strong>: what to log against today, how much room is left, and last week&#39;s time.</li><li><strong>For owners and managers, the same summary as the home page</strong>: projects off course or still needing setup, who&#39;s over capacity, and for owners, last month&#39;s money.</li><li><strong>One inbox for everything waiting on you</strong>: time-off requests, time approvals, and items flagged for attention, grouped by kind.</li><li><strong>A home page brief</strong> that answers &quot;how are we doing?&quot; in one screen.</li></ul><h3 id="running-vera" tabindex="-1">Running VERA <a class="header-anchor" href="#running-vera" aria-label="Permalink to &quot;Running VERA&quot;">​</a></h3><ul><li><strong>Set up for you</strong> in about a day.</li><li><strong>A web console</strong>, no installs, that works on a phone browser.</li><li><strong>Slack is optional.</strong> Teams without it get every message by email.</li><li><strong>An audit log</strong> of everything created and every change to recorded time.</li><li><strong>A status page</strong> showing whether every part of VERA is working.</li></ul><h2 id="see-it" tabindex="-1">See it <a class="header-anchor" href="#see-it" aria-label="Permalink to &quot;See it&quot;">​</a></h2><p>The <a href="/in-action.html">See it in action</a> page shows the real console with invented data, generated by the same code that runs the product.</p><p><a href="https://calendly.com/getvera" target="_blank" rel="noreferrer"><strong>Book a 30-minute call →</strong></a></p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes {#notes}&quot;">​</a></h2><p>* How the comparison is worked out:</p><ul><li><strong>Harvest</strong> is the renewal <a href="https://leaveharvest.com/" target="_blank" rel="noreferrer">Cumulus Vision published</a> for a six-seat consultancy: Enterprise seats at $17.50 a month each, plus a flat $599 a month &quot;Unlimited&quot; usage fee. Harvest&#39;s other billing option charges by projects, clients, tasks and invoicing instead; for that firm it came to about the same. Harvest doesn&#39;t publish its usage rates, so your bill may differ, and the price shown when you sign up doesn&#39;t include them. Forecast, Harvest&#39;s separate capacity planning tool, isn&#39;t included.</li><li><strong>VERA</strong> is the <a href="/pricing.html">Pricing</a> page&#39;s price for the revenue band your team falls in: team size times revenue per person. Every seat, project, client and invoice is included, and there is no usage fee.</li><li>Both are billed monthly.</li></ul>',33))])}const f=a(d,[["render",l]]);export{m as __pageData,f as default};
